api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.services-section {
  padding: 70px 20px;

  background: #ffffff;
}

.services-container {
  max-width: 1200px;
  margin: auto;
}

.section-heading {
  text-align: center;
  margin-bottom: 45px;
}

.section-heading span {
  font-size: 12px;
  font-weight: 700;

  color: #0f766e;

  letter-spacing: 1px;
}

.section-heading h2 {
  margin-top: 10px;

  font-size: 32px;

  color: #111827;
}

.section-heading p {
  margin-top: 10px;

  color: #6b7280;
}

.services-grid {
  display: grid;

  grid-template-columns:
    repeat(4, 1fr);

  gap: 20px;
}

.service-card {
  padding: 25px;

  border: 1px solid #e5e7eb;

  border-radius: 14px;

  background: white;

  text-decoration: none;

  transition: all 0.2s ease;
}

.service-card:hover {
  transform: translateY(-4px);

  box-shadow:
    0 10px 25px rgba(0,0,0,0.08);

  border-color: #99f6e4;
}

.service-icon {
  width: 48px;
  height: 48px;

  border-radius: 10px;

  background: #f0fdfa;

  color: #0f766e;

  display: flex;
  align-items: center;
  justify-content: center;

  font-size: 20px;
}

.service-content h3 {
  margin-top: 18px;

  font-size: 17px;

  color: #111827;
}

.service-content p {
  margin-top: 8px;

  font-size: 13px;

  line-height: 1.6;

  color: #6b7280;
}

.service-link {
  display: block;

  margin-top: 15px;

  color: #0f766e;

  font-size: 13px;

  font-weight: 600;
}

@media(max-width: 900px) {

  .services-grid {
    grid-template-columns:
      repeat(2, 1fr);
  }

}

@media(max-width: 600px) {

  .services-grid {
    grid-template-columns: 1fr;
  }

}

